INSERT INTO public.record_statistic
SELECT populated.* FROM jsonb_populate_record(NULL::public.record_statistic,
 $2 || jsonb_build_object('id_record',$1,'date_created',clock_timestamp(),'date_updated',clock_timestamp())) populated
ON CONFLICT(id_record) DO UPDATE SET
 (frame_count,time,distance,distance_in_air,distance_on_ground,time_in_air,time_on_ground,average_speed,max_speed,arms_up_count,arms_up_time,brake_count,brake_time,turn_left_count,turn_left_time,turn_right_count,turn_right_time,horn_count,horn_time,time_soap_wheels,time_offroad_wheels,time_paraglider,distance_on_tarmac,distance_on_grass,distance_on_sand,distance_on_ice1,distance_on_soap,time_on_tarmac,time_on_grass,time_on_sand,time_on_ice1,time_on_soap,distance_on_1_wheel,distance_on_2_wheels,distance_on_3_wheels,distance_on_4_wheels,time_on_1_wheel,time_on_2_wheels,time_on_3_wheels,time_on_4_wheels,distance_slipping,distance_paraglider,distance_offroad_wheels,distance_soap_wheels,distance_on_monorail,distance_parked,time_slipping,time_on_monorail,time_parked,average_velocity,max_velocity,average_angular_velocity,max_angular_velocity,average_gforce,max_gforce,distance_ragdoll,time_ragdoll,ghost_version,has_input_data,has_air_data,has_wheel_data,has_slip_data,has_state_data,has_surface_data,has_velocity_data,has_ragdoll_data,time_any_driver_input,driver_input_transition_count,distance_on_wood,distance_on_mud,time_on_wood,time_on_mud,distance_on_ice2,distance_on_ice3,time_on_ice2,time_on_ice3,record_eligible,distance_on_unknown,time_on_unknown) =
 (EXCLUDED.frame_count,EXCLUDED.time,EXCLUDED.distance,EXCLUDED.distance_in_air,EXCLUDED.distance_on_ground,EXCLUDED.time_in_air,EXCLUDED.time_on_ground,EXCLUDED.average_speed,EXCLUDED.max_speed,EXCLUDED.arms_up_count,EXCLUDED.arms_up_time,EXCLUDED.brake_count,EXCLUDED.brake_time,EXCLUDED.turn_left_count,EXCLUDED.turn_left_time,EXCLUDED.turn_right_count,EXCLUDED.turn_right_time,EXCLUDED.horn_count,EXCLUDED.horn_time,EXCLUDED.time_soap_wheels,EXCLUDED.time_offroad_wheels,EXCLUDED.time_paraglider,EXCLUDED.distance_on_tarmac,EXCLUDED.distance_on_grass,EXCLUDED.distance_on_sand,EXCLUDED.distance_on_ice1,EXCLUDED.distance_on_soap,EXCLUDED.time_on_tarmac,EXCLUDED.time_on_grass,EXCLUDED.time_on_sand,EXCLUDED.time_on_ice1,EXCLUDED.time_on_soap,EXCLUDED.distance_on_1_wheel,EXCLUDED.distance_on_2_wheels,EXCLUDED.distance_on_3_wheels,EXCLUDED.distance_on_4_wheels,EXCLUDED.time_on_1_wheel,EXCLUDED.time_on_2_wheels,EXCLUDED.time_on_3_wheels,EXCLUDED.time_on_4_wheels,EXCLUDED.distance_slipping,EXCLUDED.distance_paraglider,EXCLUDED.distance_offroad_wheels,EXCLUDED.distance_soap_wheels,EXCLUDED.distance_on_monorail,EXCLUDED.distance_parked,EXCLUDED.time_slipping,EXCLUDED.time_on_monorail,EXCLUDED.time_parked,EXCLUDED.average_velocity,EXCLUDED.max_velocity,EXCLUDED.average_angular_velocity,EXCLUDED.max_angular_velocity,EXCLUDED.average_gforce,EXCLUDED.max_gforce,EXCLUDED.distance_ragdoll,EXCLUDED.time_ragdoll,EXCLUDED.ghost_version,EXCLUDED.has_input_data,EXCLUDED.has_air_data,EXCLUDED.has_wheel_data,EXCLUDED.has_slip_data,EXCLUDED.has_state_data,EXCLUDED.has_surface_data,EXCLUDED.has_velocity_data,EXCLUDED.has_ragdoll_data,EXCLUDED.time_any_driver_input,EXCLUDED.driver_input_transition_count,EXCLUDED.distance_on_wood,EXCLUDED.distance_on_mud,EXCLUDED.time_on_wood,EXCLUDED.time_on_mud,EXCLUDED.distance_on_ice2,EXCLUDED.distance_on_ice3,EXCLUDED.time_on_ice2,EXCLUDED.time_on_ice3,EXCLUDED.record_eligible,EXCLUDED.distance_on_unknown,EXCLUDED.time_on_unknown),
 date_updated=clock_timestamp()
WHERE (to_jsonb(record_statistic)-ARRAY['date_created','date_updated'])
 IS DISTINCT FROM (to_jsonb(EXCLUDED)-ARRAY['date_created','date_updated']);
